  // ===== 私有方法 =====

  private generateExecutiveSummary(project: Project): string {
    const parts: string[] = [];

    parts.push(
      `${project.name}是一家${project.industry}领域的${project.fundraising.currentStage}阶段创业公司，` +
      `主要提供${project.product.uniqueValueProposition}。`
    );

    if (project.market.tam) {
      parts.push(
        `公司瞄准的是一个TAM达${this.formatNumber(project.market.tam)}美元的大市场` +
        (project.market.marketGrowthRate
          ? `，年增长率${(project.market.marketGrowthRate * 100).toFixed(0)}%。`
          : '。')
      );
    }

    if (project.team.founders.length > 0) {
      const founderNames = project.team.founders.map(f => f.name).join('、');
      parts.push(`公司由${founderNames}等${project.team.founders.length}位创始人于${project.foundedDate || '近期'}创立。`);
    }

    if (project.traction) {
      if (project.traction.customers && project.traction.customers > 0) {
        parts.push(`目前已服务${project.traction.customers}+付费客户`);
      }
      if (project.traction.users && project.traction.users > 0) {
        parts.push(`，拥有${project.traction.users}+用户`);
      }
    }

    if (project.financials.revenue && project.financials.revenue.current > 0) {
      parts.push(
        `，年收入${this.formatNumber(project.financials.revenue.current)}美元` +
        (project.financials.metrics?.grossMargin
          ? `，毛利率${(project.financials.metrics.grossMargin * 100).toFixed(0)}%。`
          : '。')
      );
    } else {
      parts.push('。');
    }

    parts.push(
      `\n公司正在寻求${this.formatNumber(project.fundraising.targetAmount)}美元的${project.fundraising.currentStage}融资，` +
      `资金主要用于${project.fundraising.useOfFunds.map(u => u.category).slice(0, 3).join('、')}等方面。`
    );

    return parts.join('');
  }

  private identifyInvestmentHighlights(project: Project): string[] {
    const highlights: string[] = [];

    // 市场机会
    if (project.market.tam && project.market.tam >= 10_000_000_000) {
      highlights.push(`巨大的市场机会：TAM超过${this.formatNumber(project.market.tam)}美元`);
    }

    if (project.market.marketGrowthRate && project.market.marketGrowthRate >= 0.2) {
      highlights.push(`高增长市场：年增长率${(project.market.marketGrowthRate * 100).toFixed(0)}%`);
    }

    // 产品与技术
    if (project.product.stage === 'launched' || project.product.stage === 'scaling') {
      highlights.push('产品已推向市场，技术风险较低');
    }

    if (project.product.keyFeatures.length >= 5) {
      highlights.push('产品功能丰富，具备明显的差异化优势');
    }

    // 牵引力
    if (project.traction) {
      if (project.traction.customers && project.traction.customers >= 100) {
        highlights.push(`强劲的市场牵引力：${project.traction.customers}+付费客户`);
      }

      if (project.traction.partnerships && project.traction.partnerships.length >= 3) {
        highlights.push(`建立了多个战略合作伙伴关系，包括${project.traction.partnerships.slice(0, 2).join('、')}等`);
      }
    }

    // 财务
    if (project.financials.revenue && project.financials.revenue.current >= 1_000_000) {
      highlights.push(`年收入${this.formatNumber(project.financials.revenue.current)}美元，商业模式已验证`);
    }

    if (project.financials.metrics) {
      if (project.financials.metrics.grossMargin && project.financials.metrics.grossMargin >= 0.7) {
        highlights.push(`优秀的毛利率：${(project.financials.metrics.grossMargin * 100).toFixed(0)}%`);
      }

      if (project.financials.metrics.lifetimeValue && project.financials.metrics.customerAcquisitionCost) {
        const ratio = project.financials.metrics.lifetimeValue / project.financials.metrics.customerAcquisitionCost;
        if (ratio >= 3) {
          highlights.push(`健康的单位经济模型：LTV/CAC = ${ratio.toFixed(1)}`);
        }
      }
    }

    // 团队
    if (project.team.founders.length >= 2 && project.team.founders.length <= 3) {
      highlights.push('理想的创始团队配置，具备互补技能');
    }

    // 竞争
    if (project.market.competitors.length <= 3) {
      highlights.push('竞争较少，有机会建立市场领导地位');
    }

    // 如果亮点少于3个，添加一些通用亮点
    if (highlights.length < 3) {
      highlights.push(`清晰的价值主张：${project.product.uniqueValueProposition.substring(0, 80)}`);
      highlights.push(`瞄准${project.targetMarket}这一具有增长潜力的市场`);
    }

    return highlights.slice(0, 5); // 最多5个亮点
  }

  private analyzeMarketOpportunity(project: Project): InvestmentMemo['marketOpportunity'] {
    const { market } = project;

    let sizeDescription = '';
    if (market.tam) {
      sizeDescription = `TAM（总体市场规模）约为${this.formatNumber(market.tam)}美元`;
      if (market.sam) {
        sizeDescription += `，SAM（可服务市场）约为${this.formatNumber(market.sam)}美元`;
      }
      if (market.som) {
        sizeDescription += `，SOM（可获得市场）约为${this.formatNumber(market.som)}美元`;
      }
      sizeDescription += '。';
    } else {
      sizeDescription = '市场规模有待进一步量化分析。';
    }

    let growthDescription = '';
    if (market.marketGrowthRate) {
      const rate = (market.marketGrowthRate * 100).toFixed(1);
      if (market.marketGrowthRate >= 0.2) {
        growthDescription = `市场正以年均${rate}%的高速增长，属于快速增长期。`;
      } else if (market.marketGrowthRate >= 0.1) {
        growthDescription = `市场年增长率约${rate}%，保持稳健增长。`;
      } else {
        growthDescription = `市场增长率约${rate}%，相对成熟。`;
      }
    } else {
      growthDescription = '市场增长趋势有待进一步调研。';
    }

    const dynamics = `${project.targetMarket}市场当前有${market.competitors.length}个主要竞争者。` +
      (market.competitors.length <= 3
        ? '市场相对蓝海，有较大发展空间。'
        : market.competitors.length <= 7
        ? '市场竞争适中，需要明确差异化定位。'
        : '市场竞争激烈，需要强大的执行力和资源投入。');

    return {
      size: sizeDescription,
      growth: growthDescription,
      dynamics,
    };
  }

  private analyzeCompetitivePosition(project: Project): InvestmentMemo['competitivePosition'] {
    const strengths: string[] = [];
    const weaknesses: string[] = [];

    // 分析优势
    if (project.product.stage === 'launched' || project.product.stage === 'scaling') {
      strengths.push('产品已推向市场，先发优势明显');
    }

    if (project.traction?.customers && project.traction.customers >= 50) {
      strengths.push('已建立客户基础，形成网络效应');
    }

    if (project.financials.metrics?.grossMargin && project.financials.metrics.grossMargin >= 0.6) {
      strengths.push('高毛利率带来定价能力和盈利空间');
    }

    project.product.keyFeatures.slice(0, 2).forEach(feature => {
      strengths.push(`产品特性：${feature}`);
    });

    // 分析劣势
    if (project.market.competitors.length > 10) {
      weaknesses.push('市场竞争者众多，面临激烈竞争');
    }

    if (!project.traction || (project.traction.customers || 0) < 10) {
      weaknesses.push('市场牵引力有限，需要加速客户获取');
    }

    if (project.team.teamSize < 10) {
      weaknesses.push('团队规模较小，执行能力有待加强');
    }

    const differentiation = project.product.uniqueValueProposition +
      (project.market.competitors.length > 0 && project.market.competitors[0].differentiation
        ? `相比主要竞争对手，${project.market.competitors[0].differentiation}`
        : '');

    return {
      strengths,
      weaknesses,
      differentiation,
    };
  }

  private assessTeam(project: Project): InvestmentMemo['teamAssessment'] {
    const overview = `团队由${project.team.founders.length}位创始人组成，当前团队规模${project.team.teamSize}人。` +
      project.team.founders.map(f => `${f.name}（${f.title}）${f.background.substring(0, 50)}...`).join('；');

    const strengths: string[] = [];
    const gaps: string[] = [];

    // 团队优势
    if (project.team.founders.length >= 2 && project.team.founders.length <= 3) {
      strengths.push('创始团队规模合理，便于决策和执行');
    }

    if (project.team.founders.some(f =>
      f.background.toLowerCase().includes('experience') ||
      f.background.toLowerCase().includes('founder')
    )) {
      strengths.push('创始人具备相关行业经验或创业经验');
    }

    if (project.team.teamSize >= 10) {
      strengths.push('团队已具备一定规模，组织能力初步形成');
    }

    // 团队缺口
    if (project.team.founders.length === 1) {
      gaps.push('单一创始人，建议引入联合创始人分担风险');
    }

    if (project.team.teamSize < 5) {
      gaps.push('团队规模较小，需要快速扩充核心岗位');
    }

    if (!project.team.keyHires || project.team.keyHires.length === 0) {
      gaps.push('缺少关键岗位招聘计划说明');
    }

    return {
      overview,
      strengths,
      gaps,
    };
  }

  private analyzeFinancials(project: Project): InvestmentMemo['financialAnalysis'] {
    const currentMetrics: Record<string, any> = {};

    if (project.financials.revenue) {
      currentMetrics['当前收入'] = `$${this.formatNumber(project.financials.revenue.current)}`;
    } else {
      currentMetrics['当前收入'] = 'Pre-revenue';
    }

    if (project.financials.metrics) {
      const m = project.financials.metrics;
      if (m.arr) currentMetrics['ARR'] = `$${this.formatNumber(m.arr)}`;
      if (m.mrr) currentMetrics['MRR'] = `$${this.formatNumber(m.mrr)}`;
      if (m.grossMargin) currentMetrics['毛利率'] = `${(m.grossMargin * 100).toFixed(0)}%`;
      if (m.customerAcquisitionCost) currentMetrics['CAC'] = `$${this.formatNumber(m.customerAcquisitionCost)}`;
      if (m.lifetimeValue) currentMetrics['LTV'] = `$${this.formatNumber(m.lifetimeValue)}`;
      if (m.churnRate) currentMetrics['月流失率'] = `${(m.churnRate * 100).toFixed(1)}%`;
    }

    if (project.financials.expenses) {
      currentMetrics['月消耗'] = `$${this.formatNumber(project.financials.expenses.monthly)}`;
      currentMetrics['跑道'] = `${project.financials.expenses.runway}个月`;
    }

    let projections = '财务预测';
    if (project.financials.revenue?.projected && project.financials.revenue.projected.length > 0) {
      projections = '未来收入预测：' +
        project.financials.revenue.projected
          .slice(0, 3)
          .map(p => `${p.year}年$${this.formatNumber(p.amount)}`)
          .join(', ');
    } else {
      projections = '需要提供详细的财务预测模型';
    }

    let valuation = '估值';
    if (project.fundraising.currentValuation) {
      valuation = `当前融资估值：$${this.formatNumber(project.fundraising.currentValuation)}`;
    } else {
      valuation = '估值待协商，建议使用多种估值方法综合确定';
    }

    return {
      currentMetrics,
      projections,
      valuation,
    };
  }

  private identifyInvestmentRisks(project: Project): InvestmentMemo['risks'] {
    const risks: InvestmentMemo['risks'] = [];

    // 市场风险
    if (project.market.competitors.length > 10) {
      risks.push({
        category: '市场竞争风险',
        description: '市场竞争激烈，存在多个成熟竞争对手',
        severity: 'high',
        mitigation: '聚焦细分市场，建立差异化优势和护城河',
      });
    }

    // 执行风险
    if (project.team.founders.length === 1) {
      risks.push({
        category: '团队风险',
        description: '单一创始人，关键人物依赖度高',
        severity: 'high',
        mitigation: '引入联合创始人，建立继任计划',
      });
    }

    // 财务风险
    if (!project.financials.revenue || project.financials.revenue.current === 0) {
      risks.push({
        category: '收入风险',
        description: '尚未产生收入，商业模式未经验证',
        severity: 'medium',
        mitigation: '尽快获取付费客户，证明产品市场契合度',
      });
    }

    if (project.financials.expenses && project.financials.expenses.runway < 6) {
      risks.push({
        category: '现金流风险',
        description: `现金跑道不足6个月（剩余${project.financials.expenses.runway}个月）`,
        severity: 'high',
        mitigation: '立即启动融资，同时控制开支延长跑道',
      });
    }

    // 产品风险
    if (project.product.stage === 'idea' || project.product.stage === 'prototype') {
      risks.push({
        category: '产品风险',
        description: '产品尚在早期阶段，技术和市场验证不足',
        severity: 'high',
        mitigation: '加快产品开发，尽早推向市场获取反馈',
      });
    }

    // 规模化风险
    if (!project.traction || (project.traction.customers || 0) < 10) {
      risks.push({
        category: '规模化风险',
        description: '缺乏足够的市场牵引力，规模化路径不明确',
        severity: 'medium',
        mitigation: '优化用户获取策略，建立可持续的增长引擎',
      });
    }

    return risks;
  }

  private generateRecommendation(project: Project): InvestmentMemo['recommendation'] {
    // 简单的评分逻辑
    let score = 0;

    // 市场 (0-30)
    if (project.market.tam && project.market.tam >= 10_000_000_000) score += 30;
    else if (project.market.tam && project.market.tam >= 1_000_000_000) score += 20;
    else score += 10;

    // 团队 (0-25)
    if (project.team.founders.length >= 2 && project.team.founders.length <= 3) score += 25;
    else if (project.team.founders.length >= 2) score += 15;
    else score += 5;

    // 产品 (0-20)
    const productScores: Record<string, number> = {
      'idea': 5,
      'prototype': 10,
      'mvp': 15,
      'launched': 18,
      'scaling': 20,
    };
    score += productScores[project.product.stage] || 10;

    // 牵引力 (0-15)
    if (project.traction?.customers && project.traction.customers >= 100) score += 15;
    else if (project.traction?.customers && project.traction.customers >= 10) score += 10;
    else score += 2;

    // 财务 (0-10)
    if (project.financials.revenue && project.financials.revenue.current >= 1_000_000) score += 10;
    else if (project.financials.revenue && project.financials.revenue.current > 0) score += 5;

    // 决策
    let decision: InvestmentMemo['recommendation']['decision'];
    let reasoning: string;
    let nextSteps: string[];

    if (score >= 80) {
      decision = 'strong-yes';
      reasoning = '项目在市场、团队、产品和牵引力等多个维度表现优秀，具有很高的投资价值。建议快速推进到下一阶段。';
      nextSteps = [
        '安排与创始团队的深度访谈',
        '进行客户访谈和市场调研',
        '启动法律和财务尽职调查',
        '准备投资条款清单（Term Sheet）',
      ];
    } else if (score >= 65) {
      decision = 'proceed';
      reasoning = '项目整体质量良好，值得进一步尽职调查。需要重点关注某些领域的风险。';
      nextSteps = [
        '深入了解团队背景和执行能力',
        '验证市场规模和增长假设',
        '评估竞争格局和差异化优势',
        '审查财务模型和关键假设',
      ];
    } else if (score >= 45) {
      decision = 'maybe';
      reasoning = '项目有一定潜力，但存在明显的风险点和不确定性。可以继续观察，但不建议立即投资。';
      nextSteps = [
        '要求创业团队提供更详细的信息',
        '等待项目在关键指标上取得进展',
        '评估是否符合我们的风险偏好',
        '考虑小额跟投或可转债等灵活结构',
      ];
    } else {
      decision = 'pass';
      reasoning = '项目当前阶段风险较高，不符合我们的投资标准。建议暂时放弃，未来可以继续关注。';
      nextSteps = [
        '礼貌回复创业团队说明原因',
        '建议团队在特定方面改进后再联系',
        '将项目加入观察名单定期review',
      ];
    }

    return {
      decision,
      reasoning,
      nextSteps,
    };
  }

  // 辅助方法
  private formatNumber(num: number): string {
    if (num >= 1_000_000_000) {
      return `${(num / 1_000_000_000).toFixed(1)}B`;
    } else if (num >= 1_000_000) {
      return `${(num / 1_000_000).toFixed(1)}M`;
    } else if (num >= 1_000) {
      return `${(num / 1_000).toFixed(1)}K`;
    }
    return num.toFixed(0);
  }
}

import type { Project, ProjectAssessment } from '../../types/project.js';

/**
 * 项目评估引擎
 * 全面评估创业项目的投资价值
 */
export class ProjectAssessor {
  /**
   * 评估项目
   */
  async assess(project: Project): Promise<ProjectAssessment> {
    const scores = {
      team: this.assessTeam(project),
      market: this.assessMarket(project),
      product: this.assessProduct(project),
      traction: this.assessTraction(project),
      financials: this.assessFinancials(project),
      overall: 0,
    };

    // 加权计算总分
    scores.overall = this.calculateOverallScore(scores);

    const strengths = this.identifyStrengths(project, scores);
    const weaknesses = this.identifyWeaknesses(project, scores);
    const risks = this.assessRisks(project);
    const recommendations = this.generateRecommendations(project, scores, weaknesses);
    const investmentReadiness = this.determineInvestmentReadiness(scores, risks);

    return {
      project,
      scores,
      strengths,
      weaknesses,
      risks,
      recommendations,
      investmentReadiness,
    };
  }

  /**
   * 评估团队 (0-100)
   */
  private assessTeam(project: Project): number {
    let score = 0;
    const { team } = project;

    // 创始人数量 (0-20)
    const founderCount = team.founders.length;
    if (founderCount >= 2 && founderCount <= 4) {
      score += 20;
    } else if (founderCount === 1) {
      score += 10;
    } else {
      score += 5;
    }

    // 创始人背景 (0-30)
    const hasRelevantBackground = team.founders.some(
      f => f.background.toLowerCase().includes('experience') ||
           f.background.toLowerCase().includes('expertise')
    );
    if (hasRelevantBackground) {
      score += 30;
    } else {
      score += 15;
    }

    // 团队规模 (0-20)
    if (team.teamSize >= 5 && team.teamSize <= 50) {
      score += 20;
    } else if (team.teamSize >= 2 && team.teamSize < 5) {
      score += 15;
    } else if (team.teamSize > 50) {
      score += 10;
    } else {
      score += 5;
    }

    // 关键岗位 (0-30)
    const hasKeyHires = team.keyHires && team.keyHires.length > 0;
    if (hasKeyHires) {
      score += 30;
    } else {
      score += 10;
    }

    return Math.min(score, 100);
  }

  /**
   * 评估市场 (0-100)
   */
  private assessMarket(project: Project): number {
    let score = 0;
    const { market } = project;

    // 市场规模 (0-40)
    if (market.tam !== undefined) {
      if (market.tam >= 10_000_000_000) { // $10B+
        score += 40;
      } else if (market.tam >= 1_000_000_000) { // $1B+
        score += 30;
      } else if (market.tam >= 100_000_000) { // $100M+
        score += 20;
      } else {
        score += 10;
      }
    }

    // 市场增长率 (0-30)
    if (market.marketGrowthRate !== undefined) {
      if (market.marketGrowthRate >= 0.3) { // 30%+
        score += 30;
      } else if (market.marketGrowthRate >= 0.15) { // 15%+
        score += 20;
      } else if (market.marketGrowthRate >= 0.05) { // 5%+
        score += 10;
      } else {
        score += 5;
      }
    }

    // 竞争格局 (0-30)
    const competitorCount = market.competitors.length;
    const hasDifferentiation = market.competitors.some(c => c.differentiation);

    if (competitorCount <= 3 && hasDifferentiation) {
      score += 30;
    } else if (competitorCount <= 5) {
      score += 20;
    } else if (competitorCount <= 10) {
      score += 10;
    } else {
      score += 5;
    }

    return Math.min(score, 100);
  }

  /**
   * 评估产品 (0-100)
   */
  private assessProduct(project: Project): number {
    let score = 0;
    const { product } = project;

    // 产品阶段 (0-40)
    const stageScores: Record<typeof product.stage, number> = {
      'idea': 5,
      'prototype': 15,
      'mvp': 25,
      'launched': 35,
      'scaling': 40,
    };
    score += stageScores[product.stage];

    // 独特价值主张 (0-30)
    const uvpLength = product.uniqueValueProposition.length;
    if (uvpLength >= 50) {
      score += 30;
    } else if (uvpLength >= 20) {
      score += 20;
    } else {
      score += 10;
    }

    // 核心功能 (0-15)
    const featureCount = product.keyFeatures.length;
    if (featureCount >= 5) {
      score += 15;
    } else if (featureCount >= 3) {
      score += 10;
    } else {
      score += 5;
    }

    // 痛点识别 (0-15)
    const painPointCount = product.customerPainPoints.length;
    if (painPointCount >= 3) {
      score += 15;
    } else if (painPointCount >= 2) {
      score += 10;
    } else {
      score += 5;
    }

    return Math.min(score, 100);
  }

  /**
   * 评估牵引力 (0-100)
   */
  private assessTraction(project: Project): number {
    if (!project.traction) {
      return 0;
    }

    let score = 0;
    const { traction } = project;

    // 客户数量 (0-30)
    if (traction.customers !== undefined) {
      if (traction.customers >= 1000) {
        score += 30;
      } else if (traction.customers >= 100) {
        score += 20;
      } else if (traction.customers >= 10) {
        score += 10;
      } else if (traction.customers > 0) {
        score += 5;
      }
    }

    // 用户数量 (0-25)
    if (traction.users !== undefined) {
      if (traction.users >= 100_000) {
        score += 25;
      } else if (traction.users >= 10_000) {
        score += 20;
      } else if (traction.users >= 1_000) {
        score += 15;
      } else if (traction.users > 0) {
        score += 10;
      }
    }

    // 合作伙伴 (0-20)
    if (traction.partnerships && traction.partnerships.length > 0) {
      score += Math.min(traction.partnerships.length * 5, 20);
    }

    // 奖项和媒体 (0-15)
    const hasAwards = traction.awards && traction.awards.length > 0;
    const hasPress = traction.press && traction.press.length > 0;
    if (hasAwards && hasPress) {
      score += 15;
    } else if (hasAwards || hasPress) {
      score += 10;
    }

    // 增长趋势 (0-10)
    if (traction.growth) {
      score += 10;
    }

    return Math.min(score, 100);
  }

  /**
   * 评估财务 (0-100)
   */
  private assessFinancials(project: Project): number {
    let score = 0;
    const { financials } = project;

    // 收入 (0-30)
    if (financials.revenue) {
      if (financials.revenue.current >= 10_000_000) { // $10M+
        score += 30;
      } else if (financials.revenue.current >= 1_000_000) { // $1M+
        score += 25;
      } else if (financials.revenue.current >= 100_000) { // $100K+
        score += 15;
      } else if (financials.revenue.current > 0) {
        score += 10;
      }
    }

    // 关键指标 (0-40)
    if (financials.metrics) {
      const { metrics } = financials;

      // 毛利率
      if (metrics.grossMargin !== undefined) {
        if (metrics.grossMargin >= 0.7) {
          score += 15;
        } else if (metrics.grossMargin >= 0.5) {
          score += 10;
        } else if (metrics.grossMargin >= 0.3) {
          score += 5;
        }
      }

      // LTV/CAC比率
      if (metrics.lifetimeValue && metrics.customerAcquisitionCost) {
        const ratio = metrics.lifetimeValue / metrics.customerAcquisitionCost;
        if (ratio >= 3) {
          score += 15;
        } else if (ratio >= 2) {
          score += 10;
        } else if (ratio >= 1) {
          score += 5;
        }
      }

      // 流失率
      if (metrics.churnRate !== undefined) {
        if (metrics.churnRate <= 0.05) { // 5%以下
          score += 10;
        } else if (metrics.churnRate <= 0.1) { // 10%以下
          score += 5;
        }
      }
    }

    // 跑道 (0-30)
    if (financials.expenses) {
      const { runway } = financials.expenses;
      if (runway >= 18) {
        score += 30;
      } else if (runway >= 12) {
        score += 20;
      } else if (runway >= 6) {
        score += 10;
      } else {
        score += 5;
      }
    }

    return Math.min(score, 100);
  }

  /**
   * 计算综合得分
   */
  private calculateOverallScore(scores: Omit<ProjectAssessment['scores'], 'overall'>): number {
    const weights = {
      team: 0.30,
      market: 0.25,
      product: 0.20,
      traction: 0.15,
      financials: 0.10,
    };

    return Math.round(
      scores.team * weights.team +
      scores.market * weights.market +
      scores.product * weights.product +
      scores.traction * weights.traction +
      scores.financials * weights.financials
    );
  }

  /**
   * 识别优势
   */
  private identifyStrengths(project: Project, scores: ProjectAssessment['scores']): string[] {
    const strengths: string[] = [];

    if (scores.team >= 80) {
      strengths.push('优秀的创始团队，具备深厚的行业背景和执行能力');
    }

    if (scores.market >= 80) {
      strengths.push('巨大的市场机会，市场规模可观且增长迅速');
    }

    if (scores.product >= 80) {
      strengths.push('产品已经较为成熟，具备清晰的价值主张和差异化优势');
    }

    if (scores.traction >= 70) {
      strengths.push('已获得显著的市场牵引力，有明确的增长趋势');
    }

    if (scores.financials >= 70) {
      strengths.push('财务指标健康，收入模式已得到验证');
    }

    // 具体特征分析
    if (project.market.tam && project.market.tam >= 10_000_000_000) {
      strengths.push(`TAM超过100亿美元，市场空间巨大`);
    }

    if (project.financials.metrics?.grossMargin && project.financials.metrics.grossMargin >= 0.7) {
      strengths.push(`毛利率${Math.round(project.financials.metrics.grossMargin * 100)}%，盈利能力强`);
    }

    if (project.traction?.customers && project.traction.customers >= 100) {
      strengths.push(`已获得${project.traction.customers}+付费客户，商业模式得到验证`);
    }

    return strengths;
  }

  /**
   * 识别劣势
   */
  private identifyWeaknesses(project: Project, scores: ProjectAssessment['scores']): string[] {
    const weaknesses: string[] = [];

    if (scores.team < 60) {
      weaknesses.push('团队需要加强，建议补充行业经验丰富的核心成员');
    }

    if (scores.market < 60) {
      weaknesses.push('市场机会有限或竞争过于激烈，需要重新评估目标市场');
    }

    if (scores.product < 60) {
      weaknesses.push('产品成熟度不足，需要加快产品迭代和功能完善');
    }

    if (scores.traction < 40) {
      weaknesses.push('缺乏市场验证，需要尽快获取早期客户并证明产品价值');
    }

    if (scores.financials < 40) {
      weaknesses.push('财务指标较弱，需要改善单位经济模型和现金流管理');
    }

    // 具体问题
    if (project.team.founders.length === 1) {
      weaknesses.push('单一创始人风险较高，建议引入联合创始人');
    }

    if (project.financials.expenses && project.financials.expenses.runway < 6) {
      weaknesses.push(`跑道仅剩${project.financials.expenses.runway}个月，需要尽快完成融资`);
    }

    if (project.market.competitors.length > 10) {
      weaknesses.push('竞争过于激烈，需要强化差异化优势');
    }

    if (project.product.stage === 'idea' || project.product.stage === 'prototype') {
      weaknesses.push('产品尚未推向市场，需要加快MVP开发和市场验证');
    }

    return weaknesses;
  }

  /**
   * 风险评估
   */
  private assessRisks(project: Project): ProjectAssessment['risks'] {
    const risks: ProjectAssessment['risks'] = [];

    // 市场风险
    if (project.market.competitors.length > 10) {
      risks.push({
        category: '市场风险',
        description: '市场竞争激烈，面临众多竞争对手',
        severity: 'high',
        mitigation: '建立清晰的差异化定位，聚焦特定细分市场',
      });
    }

    // 执行风险
    if (project.team.founders.length === 1) {
      risks.push({
        category: '执行风险',
        description: '单一创始人，关键人物风险较高',
        severity: 'medium',
        mitigation: '引入联合创始人或关键高管，建立备份机制',
      });
    }

    // 财务风险
    if (project.financials.expenses && project.financials.expenses.runway < 6) {
      risks.push({
        category: '财务风险',
        description: '现金流跑道不足6个月，面临资金压力',
        severity: 'high',
        mitigation: '立即启动融资流程，同时控制成本延长跑道',
      });
    }

    // 产品风险
    if (project.product.stage === 'idea' || project.product.stage === 'prototype') {
      risks.push({
        category: '产品风险',
        description: '产品尚未推向市场，市场接受度未知',
        severity: 'high',
        mitigation: '尽快完成MVP开发，获取早期用户反馈',
      });
    }

    // 牵引力风险
    if (!project.traction || (project.traction.customers || 0) < 10) {
      risks.push({
        category: '市场验证风险',
        description: '缺乏足够的市场验证和客户牵引力',
        severity: 'medium',
        mitigation: '聚焦获取早期付费客户，建立案例研究',
      });
    }

    return risks;
  }

  /**
   * 生成建议
   */
  private generateRecommendations(
    project: Project,
    scores: ProjectAssessment['scores'],
    weaknesses: string[]
  ): string[] {
    const recommendations: string[] = [];

    // 基于得分的建议
    if (scores.overall >= 80) {
      recommendations.push('项目整体质量优秀，建议立即启动融资流程');
      recommendations.push('可以瞄准顶级VC，争取更好的融资条件');
    } else if (scores.overall >= 60) {
      recommendations.push('项目具备融资基础，建议在改进关键弱项后启动融资');
      recommendations.push('针对性补强团队和产品，提升项目竞争力');
    } else {
      recommendations.push('项目尚不具备融资条件，建议先进行内部优化');
      recommendations.push('聚焦产品开发和早期市场验证，积累更多牵引力');
    }

    // 针对性建议
    if (scores.traction < 50) {
      recommendations.push('优先任务：获取早期客户，证明产品市场契合度');
    }

    if (scores.team < 70) {
      recommendations.push('考虑引入行业专家或经验丰富的联合创始人');
    }

    if (scores.financials < 50 && project.financials.revenue) {
      recommendations.push('改善单位经济模型，关注关键财务指标如LTV/CAC比率');
    }

    // 融资策略建议
    if (project.fundraising.currentStage === 'seed' || project.fundraising.currentStage === 'pre-seed') {
      recommendations.push('对于早期阶段，重点展示团队能力和市场机会');
      recommendations.push('寻找愿意承担早期风险的天使投资人或种子基金');
    } else {
      recommendations.push('对于成长阶段，需要展示清晰的收入增长和单位经济模型');
      recommendations.push('目标机构应该在你的行业有专业认知和资源网络');
    }

    return recommendations;
  }

  /**
   * 判断融资准备度
   */
  private determineInvestmentReadiness(
    scores: ProjectAssessment['scores'],
    risks: ProjectAssessment['risks']
  ): ProjectAssessment['investmentReadiness'] {
    const highRisks = risks.filter(r => r.severity === 'high').length;

    if (scores.overall >= 80 && highRisks === 0) {
      return 'highly-ready';
    } else if (scores.overall >= 65 && highRisks <= 1) {
      return 'ready';
    } else if (scores.overall >= 50) {
      return 'needs-work';
    } else {
      return 'not-ready';
    }
  }
}

import type { Project } from '../../types/project.js';
import type { Investor, InvestorMatch } from '../../types/investor.js';

/**
 * 投资人匹配引擎
 * 基于项目特征匹配合适的投资机构
 */
export class InvestorMatcher {
  private investors: Investor[] = [];

  constructor(investors: Investor[]) {
    this.investors = investors;
  }

  /**
   * 为项目匹配投资人
   */
  async matchInvestors(project: Project, topN: number = 20): Promise<InvestorMatch[]> {
    const matches: InvestorMatch[] = [];

    for (const investor of this.investors) {
      const matchResult = this.calculateMatch(project, investor);

      if (matchResult.matchScore > 0) {
        matches.push(matchResult);
      }
    }

    // 按匹配分数排序
    matches.sort((a, b) => b.matchScore - a.matchScore);

    // 返回前N个
    return matches.slice(0, topN);
  }

  /**
   * 计算项目与投资人的匹配度
   */
  private calculateMatch(project: Project, investor: Investor): InvestorMatch {
    let score = 0;
    const maxScore = 100;
    const matchReasons: string[] = [];
    const concerns: string[] = [];

    // 1. 融资阶段匹配 (0-25分)
    if (investor.strategy.stages.includes(project.fundraising.currentStage)) {
      score += 25;
      matchReasons.push(`投资阶段完全匹配（${project.fundraising.currentStage}）`);
    } else {
      // 检查相邻阶段
      const stageOrder = ['pre-seed', 'seed', 'series-a', 'series-b', 'series-c', 'series-d-plus'];
      const projectStageIndex = stageOrder.indexOf(project.fundraising.currentStage);
      const hasAdjacentStage = investor.strategy.stages.some(s => {
        const investorStageIndex = stageOrder.indexOf(s);
        return Math.abs(investorStageIndex - projectStageIndex) === 1;
      });

      if (hasAdjacentStage) {
        score += 15;
        matchReasons.push(`投资阶段接近（可考虑）`);
      } else {
        concerns.push(`投资阶段不匹配（机构关注：${investor.strategy.stages.join(', ')}）`);
      }
    }

    // 2. 行业匹配 (0-25分)
    if (investor.strategy.industries.includes(project.industry)) {
      score += 25;
      matchReasons.push(`行业完全匹配（${project.industry}）`);

      // 检查细分行业
      if (investor.strategy.subIndustries && project.subIndustry) {
        if (investor.strategy.subIndustries.includes(project.subIndustry)) {
          score += 5; // 额外加分
          matchReasons.push(`细分领域也匹配（${project.subIndustry}）`);
        }
      }
    } else {
      concerns.push(`行业不在机构主要投资范围（机构关注：${investor.strategy.industries.join(', ')}）`);
    }

    // 3. 投资金额匹配 (0-20分)
    const targetAmount = project.fundraising.targetAmount;
    const { min, max, typical } = investor.strategy.investmentRange;

    if (targetAmount >= min && targetAmount <= max) {
      // 在范围内
      const closenessToTypical = 1 - Math.abs(targetAmount - typical) / typical;
      score += Math.round(20 * Math.max(0.5, closenessToTypical));
      matchReasons.push(`投资金额在范围内（$${this.formatNumber(min)}-${this.formatNumber(max)}）`);
    } else if (targetAmount < min) {
      score += 5;
      concerns.push(`融资金额低于机构通常投资额（最低$${this.formatNumber(min)}）`);
    } else {
      concerns.push(`融资金额超过机构通常投资额（最高$${this.formatNumber(max)}）`);
    }

    // 4. 地域匹配 (0-15分)
    const projectRegion = this.getRegion(project.location);
    if (investor.strategy.geographicFocus.includes(projectRegion) ||
        investor.strategy.geographicFocus.includes('global')) {
      score += 15;
      matchReasons.push(`地域匹配（${projectRegion}）`);
    } else {
      score += 5; // 部分分数，因为很多机构会考虑非重点地区的优质项目
      concerns.push(`地域不是机构主要关注区域（机构关注：${investor.strategy.geographicFocus.join(', ')}）`);
    }

    // 5. 商业模式匹配 (0-10分)
    if (investor.strategy.businessModels &&
        investor.strategy.businessModels.includes(project.businessModel)) {
      score += 10;
      matchReasons.push(`商业模式匹配（${project.businessModel}）`);
    }

    // 6. 特殊关注领域匹配 (0-5分 bonus)
    if (investor.strategy.specialFocus) {
      const projectKeywords = [
        project.name.toLowerCase(),
        project.description.toLowerCase(),
        project.product.description.toLowerCase(),
      ].join(' ');

      const hasSpecialMatch = investor.strategy.specialFocus.some(focus =>
        projectKeywords.includes(focus.toLowerCase())
      );

      if (hasSpecialMatch) {
        score += 5;
        matchReasons.push('项目符合机构特殊关注主题');
      }
    }

    // 7. 投资风格匹配分析（不计分，仅用于策略建议）
    let approachStrategy = '';
    if (investor.investmentStyle) {
      const { leadInvestor, followOn, handsOn } = investor.investmentStyle;

      if (leadInvestor) {
        approachStrategy += '该机构偏好领投，适合作为主要投资方。';
      } else if (followOn) {
        approachStrategy += '该机构主要做跟投，需要先找到领投方。';
      }

      if (handsOn === 'very-hands-on' || handsOn === 'hands-on') {
        approachStrategy += '该机构会深度参与公司运营，可提供丰富资源支持。';
      }

      // 附加价值
      if (investor.investmentStyle.valueAdd && investor.investmentStyle.valueAdd.length > 0) {
        approachStrategy += `\n附加价值：${investor.investmentStyle.valueAdd.join('、')}。`;
      }
    }

    // 决策流程信息
    if (investor.decisionProcess?.averageTimeToDecision) {
      approachStrategy += `\n平均决策周期：${investor.decisionProcess.averageTimeToDecision}天。`;
    }

    // 联系方式建议
    if (investor.contact?.preferredContact) {
      const contactPreference = investor.contact.preferredContact;
      if (contactPreference === 'warm-intro') {
        approachStrategy += '\n最佳接触方式：通过共同人脉warm intro。';
      } else if (contactPreference === 'submission-form') {
        approachStrategy += '\n可通过官网提交BP。';
      }
    }

    // 确定优先级
    let priority: 'high' | 'medium' | 'low';
    if (score >= 80) {
      priority = 'high';
    } else if (score >= 60) {
      priority = 'medium';
    } else {
      priority = 'low';
    }

    return {
      investor,
      matchScore: Math.min(score, maxScore),
      matchReasons,
      concerns,
      approachStrategy: approachStrategy || '建议研究该机构的投资组合和投资论点，定制化接触策略。',
      priority,
    };
  }

  /**
   * 生成投资人接触策略
   */
  generateOutreachStrategy(matches: InvestorMatch[]): string {
    const lines: string[] = [];

    lines.push('# 投资人接触策略\n');

    // 高优先级
    const highPriority = matches.filter(m => m.priority === 'high');
    if (highPriority.length > 0) {
      lines.push('## 🎯 高优先级目标机构\n');
      lines.push('这些机构与您的项目高度匹配，应优先接触：\n');

      highPriority.forEach((match, index) => {
        lines.push(`### ${index + 1}. ${match.investor.name}`);
        lines.push(`**匹配度**: ${match.matchScore}分`);
        lines.push(`**匹配原因**:`);
        match.matchReasons.forEach(r => lines.push(`- ${r}`));
        if (match.concerns.length > 0) {
          lines.push(`**需要注意**:`);
          match.concerns.forEach(c => lines.push(`- ${c}`));
        }
        lines.push(`**接触策略**: ${match.approachStrategy}`);
        if (match.investor.contact?.email) {
          lines.push(`**联系邮箱**: ${match.investor.contact.email}`);
        }
        if (match.investor.contact?.submissionUrl) {
          lines.push(`**提交链接**: ${match.investor.contact.submissionUrl}`);
        }
        lines.push('');
      });
    }

    // 中优先级
    const mediumPriority = matches.filter(m => m.priority === 'medium');
    if (mediumPriority.length > 0) {
      lines.push('## 📋 中优先级备选机构\n');
      lines.push('这些机构也值得考虑，可作为第二梯队：\n');

      mediumPriority.slice(0, 10).forEach((match, index) => {
        lines.push(`**${index + 1}. ${match.investor.name}** (匹配度: ${match.matchScore}分)`);
        lines.push(`   - ${match.matchReasons[0] || '部分匹配'}`);
        if (match.concerns.length > 0) {
          lines.push(`   - ⚠️ ${match.concerns[0]}`);
        }
        lines.push('');
      });
    }

    // 总体建议
    lines.push('## 💡 总体建议\n');
    lines.push('1. **优先warm intro**: 通过共同联系人介绍，成功率更高');
    lines.push('2. **定制化BP**: 根据每个机构的投资论点定制pitch deck');
    lines.push('3. **同时接触**: 同时联系5-10家机构，不要串行');
    lines.push('4. **快速迭代**: 收集反馈，持续改进pitch');
    lines.push('5. **保持节奏**: 控制整个融资周期在2-3个月内完成');

    return lines.join('\n');
  }

  /**
   * 分析为什么某个知名机构不匹配
   */
  analyzeNonMatch(project: Project, investorName: string): string {
    const investor = this.investors.find(i =>
      i.name.toLowerCase().includes(investorName.toLowerCase())
    );

    if (!investor) {
      return `未找到名为 "${investorName}" 的投资机构信息。`;
    }

    const match = this.calculateMatch(project, investor);

    const lines: string[] = [];
    lines.push(`# ${investor.name} 匹配分析\n`);
    lines.push(`**匹配得分**: ${match.matchScore}/100\n`);

    if (match.matchScore >= 70) {
      lines.push('✅ 该机构与您的项目匹配度较高，建议接触。\n');
    } else if (match.matchScore >= 50) {
      lines.push('⚠️ 该机构与项目有一定匹配度，可以尝试，但需要注意以下问题。\n');
    } else {
      lines.push('❌ 该机构与项目匹配度较低，可能不是最佳选择。\n');
    }

    if (match.matchReasons.length > 0) {
      lines.push('**匹配点**:');
      match.matchReasons.forEach(r => lines.push(`- ${r}`));
      lines.push('');
    }

    if (match.concerns.length > 0) {
      lines.push('**不匹配原因**:');
      match.concerns.forEach(c => lines.push(`- ${c}`));
      lines.push('');
    }

    lines.push(`**机构投资策略**:`);
    lines.push(`- 关注阶段: ${investor.strategy.stages.join(', ')}`);
    lines.push(`- 关注行业: ${investor.strategy.industries.join(', ')}`);
    lines.push(`- 投资金额: $${this.formatNumber(investor.strategy.investmentRange.min)} - $${this.formatNumber(investor.strategy.investmentRange.max)}`);
    lines.push(`- 地域关注: ${investor.strategy.geographicFocus.join(', ')}`);

    if (investor.strategy.thesis) {
      lines.push(`\n**投资论点**: ${investor.strategy.thesis}`);
    }

    return lines.join('\n');
  }

  // 辅助方法
  private getRegion(location: string): any {
    const loc = location.toLowerCase();

    if (loc.includes('china') || loc.includes('beijing') || loc.includes('shanghai') ||
        loc.includes('shenzhen') || loc.includes('hangzhou') || loc.includes('中国') ||
        loc.includes('北京') || loc.includes('上海') || loc.includes('深圳')) {
      return 'china';
    }

    if (loc.includes('us') || loc.includes('usa') || loc.includes('san francisco') ||
        loc.includes('new york') || loc.includes('silicon valley') || loc.includes('america')) {
      return 'north-america';
    }

    if (loc.includes('europe') || loc.includes('uk') || loc.includes('london') ||
        loc.includes('berlin') || loc.includes('paris')) {
      return 'europe';
    }

    if (loc.includes('singapore') || loc.includes('thailand') || loc.includes('vietnam') ||
        loc.includes('indonesia') || loc.includes('malaysia')) {
      return 'southeast-asia';
    }

    if (loc.includes('japan') || loc.includes('korea') || loc.includes('taiwan') ||
        loc.includes('hong kong')) {
      return 'asia';
    }

    return 'global';
  }

  private formatNumber(num: number): string {
    if (num >= 1_000_000_000) {
      return `${(num / 1_000_000_000).toFixed(1)}B`;
    } else if (num >= 1_000_000) {
      return `${(num / 1_000_000).toFixed(1)}M`;
    } else if (num >= 1_000) {
      return `${(num / 1_000).toFixed(1)}K`;
    }
    return num.toString();
  }
}

import type { Project, PitchDeckOutline } from '../../types/project.js';

/**
 * Pitch Deck 生成器
 * 根据项目信息生成专业的 Pitch Deck 大纲和内容
 */
export class PitchDeckGenerator {
  /**
   * 生成 Pitch Deck 大纲
   */
  async generateOutline(project: Project): Promise<PitchDeckOutline> {
    const slides: PitchDeckOutline['slides'] = [];

    // 1. 封面页
    slides.push({
      number: 1,
      title: project.name,
      type: 'cover',
      keyPoints: [
        project.tagline || project.description.substring(0, 100),
        `${project.fundraising.currentStage} · ${project.industry}`,
        project.location,
      ],
      notes: '简洁有力的封面，包含公司名称、一句话描述、融资阶段',
    });

    // 2. 问题页
    slides.push({
      number: 2,
      title: '问题 / Problem',
      type: 'problem',
      keyPoints: project.product.customerPainPoints.map(p => `• ${p}`),
      notes: '清晰阐述目标客户面临的核心痛点，用数据或故事增强说服力',
    });

    // 3. 解决方案页
    slides.push({
      number: 3,
      title: '解决方案 / Solution',
      type: 'solution',
      keyPoints: [
        `核心方案：${project.product.uniqueValueProposition}`,
        ...project.product.keyFeatures.slice(0, 3).map(f => `• ${f}`),
      ],
      notes: '展示产品如何解决上述问题，强调独特价值主张',
    });

    // 4. 市场机会页
    slides.push({
      number: 4,
      title: '市场机会 / Market Opportunity',
      type: 'market',
      keyPoints: [
        project.market.tam ? `TAM: $${this.formatNumber(project.market.tam)}` : 'TAM: 市场规模待定',
        project.market.sam ? `SAM: $${this.formatNumber(project.market.sam)}` : 'SAM: 可服务市场待定',
        project.market.som ? `SOM: $${this.formatNumber(project.market.som)}` : 'SOM: 可获得市场待定',
        project.market.marketGrowthRate
          ? `市场年增长率: ${(project.market.marketGrowthRate * 100).toFixed(1)}%`
          : '市场增长迅速',
      ],
      notes: '使用TAM-SAM-SOM模型展示市场规模，配合增长趋势数据',
    });

    // 5. 产品展示页
    slides.push({
      number: 5,
      title: '产品 / Product',
      type: 'product',
      keyPoints: [
        `产品阶段：${this.translateProductStage(project.product.stage)}`,
        ...project.product.keyFeatures.map(f => `• ${f}`),
      ],
      notes: '产品截图或演示，突出核心功能和用户体验',
    });

    // 6. 商业模式页
    slides.push({
      number: 6,
      title: '商业模式 / Business Model',
      type: 'business-model',
      keyPoints: [
        `模式：${this.translateBusinessModel(project.businessModel)}`,
        `目标客户：${project.targetMarket}`,
        project.financials.revenue
          ? `当前收入：$${this.formatNumber(project.financials.revenue.current)}`
          : '收入模式验证中',
        project.financials.metrics?.grossMargin
          ? `毛利率：${(project.financials.metrics.grossMargin * 100).toFixed(1)}%`
          : '',
      ].filter(Boolean),
      notes: '清晰说明如何赚钱，客户获取和定价策略',
    });

    // 7. 牵引力/成就页
    if (project.traction) {
      slides.push({
        number: 7,
        title: '牵引力 / Traction',
        type: 'traction',
        keyPoints: [
          project.traction.customers ? `${this.formatNumber(project.traction.customers)}+ 付费客户` : '',
          project.traction.users ? `${this.formatNumber(project.traction.users)}+ 用户` : '',
          project.traction.growth ? `增长：${project.traction.growth}` : '',
          ...(project.traction.partnerships || []).slice(0, 3).map(p => `合作伙伴：${p}`),
          ...(project.traction.awards || []).slice(0, 2).map(a => `获奖：${a}`),
        ].filter(Boolean),
        notes: '用图表展示增长曲线，突出关键里程碑',
      });
    }

    // 8. 竞争格局页
    slides.push({
      number: slides.length + 1,
      title: '竞争格局 / Competition',
      type: 'competition',
      keyPoints: [
        '主要竞争对手：',
        ...project.market.competitors.slice(0, 4).map(c =>
          `• ${c.name}${c.differentiation ? ` - 我们的优势: ${c.differentiation}` : ''}`
        ),
      ],
      notes: '使用竞争矩阵或对比表格，清晰展示差异化优势',
    });

    // 9. 团队页
    slides.push({
      number: slides.length + 1,
      title: '团队 / Team',
      type: 'team',
      keyPoints: [
        ...project.team.founders.map(f =>
          `${f.name} - ${f.title}: ${f.background.substring(0, 80)}`
        ),
        `团队规模：${project.team.teamSize}人`,
        ...(project.team.keyHires || []).slice(0, 2).map(h => `关键岗位：${h}`),
      ],
      notes: '创始人照片 + 核心背景，强调行业经验和互补性',
    });

    // 10. 财务预测页
    if (project.financials.revenue?.projected) {
      slides.push({
        number: slides.length + 1,
        title: '财务预测 / Financials',
        type: 'financials',
        keyPoints: [
          '收入预测：',
          ...project.financials.revenue.projected.slice(0, 3).map(p =>
            `${p.year}年: $${this.formatNumber(p.amount)}`
          ),
          project.financials.metrics?.arr ? `ARR: $${this.formatNumber(project.financials.metrics.arr)}` : '',
          project.financials.metrics?.mrr ? `MRR: $${this.formatNumber(project.financials.metrics.mrr)}` : '',
        ].filter(Boolean),
        notes: '使用柱状图或折线图展示收入增长预测，附关键假设',
      });
    }

    // 11. 融资需求页
    slides.push({
      number: slides.length + 1,
      title: '融资需求 / The Ask',
      type: 'ask',
      keyPoints: [
        `融资阶段：${this.translateFundingStage(project.fundraising.currentStage)}`,
        `融资金额：$${this.formatNumber(project.fundraising.targetAmount)}`,
        project.fundraising.currentValuation
          ? `估值：$${this.formatNumber(project.fundraising.currentValuation)}`
          : '',
        '资金用途：',
        ...project.fundraising.useOfFunds.map(u =>
          `• ${u.category} (${u.percentage}%): ${u.description}`
        ),
      ].filter(Boolean),
      notes: '清晰说明融资金额、估值和具体用途，配合时间线',
    });

    // 12. 愿景页
    slides.push({
      number: slides.length + 1,
      title: '愿景 / Vision',
      type: 'vision',
      keyPoints: [
        '我们的愿景是...',
        '未来3-5年发展规划',
        '潜在退出路径（IPO / M&A）',
      ],
      notes: '描绘公司的长远愿景和对行业的影响',
    });

    return { slides };
  }

  /**
   * 生成详细内容（用于BP文档）
   */
  async generateBusinessPlan(project: Project): Promise<string> {
    const sections: string[] = [];

    // 执行摘要
    sections.push(`# ${project.name} - 商业计划书`);
    sections.push(`\n## 执行摘要\n`);
    sections.push(project.description);
    sections.push(`\n**行业**: ${project.industry}`);
    sections.push(`**商业模式**: ${this.translateBusinessModel(project.businessModel)}`);
    sections.push(`**融资阶段**: ${this.translateFundingStage(project.fundraising.currentStage)}`);
    sections.push(`**融资金额**: $${this.formatNumber(project.fundraising.targetAmount)}`);

    // 问题与解决方案
    sections.push(`\n## 问题与解决方案\n`);
    sections.push(`### 客户痛点\n`);
    project.product.customerPainPoints.forEach(p => {
      sections.push(`- ${p}`);
    });
    sections.push(`\n### 我们的解决方案\n`);
    sections.push(project.product.description);
    sections.push(`\n**独特价值主张**: ${project.product.uniqueValueProposition}\n`);

    // 市场分析
    sections.push(`\n## 市场分析\n`);
    sections.push(`**目标市场**: ${project.targetMarket}\n`);
    if (project.market.tam) {
      sections.push(`- **TAM** (Total Addressable Market): $${this.formatNumber(project.market.tam)}`);
    }
    if (project.market.sam) {
      sections.push(`- **SAM** (Serviceable Addressable Market): $${this.formatNumber(project.market.sam)}`);
    }
    if (project.market.som) {
      sections.push(`- **SOM** (Serviceable Obtainable Market): $${this.formatNumber(project.market.som)}`);
    }
    if (project.market.marketGrowthRate) {
      sections.push(`- **市场增长率**: ${(project.market.marketGrowthRate * 100).toFixed(1)}% CAGR`);
    }

    // 竞争分析
    sections.push(`\n### 竞争格局\n`);
    project.market.competitors.forEach(c => {
      sections.push(`**${c.name}**`);
      if (c.description) sections.push(`  - ${c.description}`);
      if (c.differentiation) sections.push(`  - 我们的差异化: ${c.differentiation}`);
    });

    // 产品
    sections.push(`\n## 产品\n`);
    sections.push(`**当前阶段**: ${this.translateProductStage(project.product.stage)}\n`);
    sections.push(`### 核心功能\n`);
    project.product.keyFeatures.forEach(f => {
      sections.push(`- ${f}`);
    });

    // 商业模式
    sections.push(`\n## 商业模式\n`);
    sections.push(`**模式类型**: ${this.translateBusinessModel(project.businessModel)}`);
    sections.push(`**目标客户**: ${project.targetMarket}`);

    // 团队
    sections.push(`\n## 团队\n`);
    sections.push(`**团队规模**: ${project.team.teamSize}人\n`);
    sections.push(`### 创始团队\n`);
    project.team.founders.forEach(f => {
      sections.push(`**${f.name}** - ${f.title}`);
      sections.push(`${f.background}`);
      if (f.linkedin) sections.push(`[LinkedIn](${f.linkedin})`);
      sections.push('');
    });

    // 财务
    if (project.financials.revenue) {
      sections.push(`\n## 财务状况\n`);
      sections.push(`**当前收入**: $${this.formatNumber(project.financials.revenue.current)}`);

      if (project.financials.revenue.projected.length > 0) {
        sections.push(`\n### 收入预测\n`);
        project.financials.revenue.projected.forEach(p => {
          sections.push(`- ${p.year}年: $${this.formatNumber(p.amount)}`);
        });
      }

      if (project.financials.metrics) {
        sections.push(`\n### 关键指标\n`);
        const m = project.financials.metrics;
        if (m.arr) sections.push(`- ARR: $${this.formatNumber(m.arr)}`);
        if (m.mrr) sections.push(`- MRR: $${this.formatNumber(m.mrr)}`);
        if (m.grossMargin) sections.push(`- 毛利率: ${(m.grossMargin * 100).toFixed(1)}%`);
        if (m.customerAcquisitionCost) sections.push(`- CAC: $${this.formatNumber(m.customerAcquisitionCost)}`);
        if (m.lifetimeValue) sections.push(`- LTV: $${this.formatNumber(m.lifetimeValue)}`);
        if (m.churnRate) sections.push(`- 流失率: ${(m.churnRate * 100).toFixed(1)}%`);
      }
    }

    // 牵引力
    if (project.traction) {
      sections.push(`\n## 市场牵引力\n`);
      const t = project.traction;
      if (t.customers) sections.push(`- **付费客户**: ${this.formatNumber(t.customers)}`);
      if (t.users) sections.push(`- **总用户数**: ${this.formatNumber(t.users)}`);
      if (t.growth) sections.push(`- **增长情况**: ${t.growth}`);

      if (t.partnerships && t.partnerships.length > 0) {
        sections.push(`\n### 战略合作伙伴\n`);
        t.partnerships.forEach(p => sections.push(`- ${p}`));
      }
    }

    // 融资需求
    sections.push(`\n## 融资需求\n`);
    sections.push(`**融资阶段**: ${this.translateFundingStage(project.fundraising.currentStage)}`);
    sections.push(`**融资金额**: $${this.formatNumber(project.fundraising.targetAmount)}`);
    if (project.fundraising.minimumAmount) {
      sections.push(`**最低金额**: $${this.formatNumber(project.fundraising.minimumAmount)}`);
    }
    if (project.fundraising.currentValuation) {
      sections.push(`**当前估值**: $${this.formatNumber(project.fundraising.currentValuation)}`);
    }

    sections.push(`\n### 资金用途\n`);
    project.fundraising.useOfFunds.forEach(u => {
      sections.push(`- **${u.category}** (${u.percentage}%): ${u.description}`);
    });

    // 历史融资
    if (project.fundraising.previousRounds && project.fundraising.previousRounds.length > 0) {
      sections.push(`\n### 历史融资\n`);
      project.fundraising.previousRounds.forEach(r => {
        sections.push(`- **${this.translateFundingStage(r.stage)}** (${r.date}): $${this.formatNumber(r.amount)}`);
        if (r.investors.length > 0) {
          sections.push(`  投资方: ${r.investors.join(', ')}`);
        }
      });
    }

    return sections.join('\n');
  }

  // 辅助方法
  private formatNumber(num: number): string {
    if (num >= 1_000_000_000) {
      return `${(num / 1_000_000_000).toFixed(1)}B`;
    } else if (num >= 1_000_000) {
      return `${(num / 1_000_000).toFixed(1)}M`;
    } else if (num >= 1_000) {
      return `${(num / 1_000).toFixed(1)}K`;
    }
    return num.toString();
  }

  private translateProductStage(stage: string): string {
    const map: Record<string, string> = {
      'idea': '创意阶段',
      'prototype': '原型阶段',
      'mvp': 'MVP阶段',
      'launched': '已上线',
      'scaling': '规模化增长',
    };
    return map[stage] || stage;
  }

  private translateBusinessModel(model: string): string {
    const map: Record<string, string> = {
      'b2b-saas': 'B2B SaaS',
      'b2c': 'B2C',
      'marketplace': '市场平台',
      'platform': '平台型',
      'transaction': '交易型',
      'subscription': '订阅制',
      'freemium': '免费增值',
      'enterprise': '企业服务',
      'hybrid': '混合模式',
    };
    return map[model] || model;
  }

  private translateFundingStage(stage: string): string {
    const map: Record<string, string> = {
      'pre-seed': '天使轮',
      'seed': '种子轮',
      'series-a': 'A轮',
      'series-b': 'B轮',
      'series-c': 'C轮',
      'series-d-plus': 'D轮+',
      'pre-ipo': 'Pre-IPO',
    };
    return map[stage] || stage;
  }
}

import type { Project } from '../../types/project.js';
import type {
  ValuationMethod,
  ValuationResult,
  ComprehensiveValuation,
  FinancialProjection,
  DealStructure,
} from '../../types/models.js';

/**
 * 估值引擎
 * 使用多种方法对创业公司进行估值
 */
export class ValuationEngine {
  /**
   * 综合估值分析
   */
  async comprehensiveValuation(project: Project): Promise<ComprehensiveValuation> {
    const valuationMethods: ValuationResult[] = [];

    // 应用不同估值方法
    valuationMethods.push(await this.scorecardMethod(project));
    valuationMethods.push(await this.berkusMethod(project));
    valuationMethods.push(await this.riskFactorMethod(project));

    if (project.financials.revenue && project.financials.revenue.current > 0) {
      valuationMethods.push(await this.comparableMethod(project));
    }

    // 计算推荐估值（加权平均）
    const recommendedValuation = this.calculateWeightedValuation(valuationMethods, project);

    // 获取基准数据
    const benchmarkData = this.getBenchmarkData(project);

    // 生成交易条款建议
    const dealTerms = this.suggestDealTerms(project, recommendedValuation.preMoney);

    return {
      recommendedValuation,
      valuationByMethod: valuationMethods,
      benchmarkData,
      dealTerms,
      analysis: this.generateAnalysis(project, recommendedValuation, valuationMethods),
      risks: this.identifyValuationRisks(project, valuationMethods),
    };
  }

  /**
   * 记分卡法 (Scorecard Method)
   * 适用于早期创业公司
   */
  private async scorecardMethod(project: Project): Promise<ValuationResult> {
    // 基准估值（根据地区和行业）
    const baselineValuation = this.getBaselineValuation(project);

    // 评分因素及权重
    const factors = {
      team: { weight: 0.30, score: 0 },
      market: { weight: 0.25, score: 0 },
      product: { weight: 0.15, score: 0 },
      competition: { weight: 0.10, score: 0 },
      marketing: { weight: 0.10, score: 0 },
      funding: { weight: 0.05, score: 0 },
      other: { weight: 0.05, score: 0 },
    };

    // 团队评分 (0-150%)
    const founderCount = project.team.founders.length;
    const hasExperience = project.team.founders.some(f =>
      f.background.toLowerCase().includes('experience') ||
      f.background.toLowerCase().includes('founder')
    );

    if (founderCount >= 2 && founderCount <= 3 && hasExperience) {
      factors.team.score = 130;
    } else if (founderCount >= 2) {
      factors.team.score = 110;
    } else {
      factors.team.score = 80;
    }

    // 市场评分 (0-150%)
    if (project.market.tam && project.market.tam >= 10_000_000_000) {
      factors.market.score = 140;
    } else if (project.market.tam && project.market.tam >= 1_000_000_000) {
      factors.market.score = 120;
    } else {
      factors.market.score = 90;
    }

    // 产品评分 (0-150%)
    const productStageScores = {
      'idea': 70,
      'prototype': 90,
      'mvp': 110,
      'launched': 130,
      'scaling': 150,
    };
    factors.product.score = productStageScores[project.product.stage] || 100;

    // 竞争评分 (0-150%)
    const competitorCount = project.market.competitors.length;
    if (competitorCount <= 3) {
      factors.competition.score = 130;
    } else if (competitorCount <= 7) {
      factors.competition.score = 100;
    } else {
      factors.competition.score = 80;
    }

    // 市场营销/牵引力评分 (0-150%)
    if (project.traction) {
      if (project.traction.customers && project.traction.customers >= 100) {
        factors.marketing.score = 140;
      } else if (project.traction.customers && project.traction.customers >= 10) {
        factors.marketing.score = 120;
      } else if (project.traction.users && project.traction.users >= 1000) {
        factors.marketing.score = 110;
      } else {
        factors.marketing.score = 90;
      }
    } else {
      factors.marketing.score = 80;
    }

    // 融资需求评分 (0-150%)
    factors.funding.score = 100;

    // 其他因素 (0-150%)
    factors.other.score = 100;

    // 计算加权调整系数
    let adjustmentFactor = 0;
    for (const [key, factor] of Object.entries(factors)) {
      adjustmentFactor += (factor.score / 100) * factor.weight;
    }

    const valuation = Math.round(baselineValuation * adjustmentFactor);

    return {
      method: 'scorecard' as ValuationMethod,
      valuation,
      range: {
        low: Math.round(valuation * 0.7),
        mid: valuation,
        high: Math.round(valuation * 1.3),
      },
      assumptions: [
        {
          key: '基准估值',
          value: baselineValuation,
          rationale: `基于${project.location}地区${project.industry}行业的${project.fundraising.currentStage}阶段基准`,
        },
        {
          key: '团队因素',
          value: `${factors.team.score}%`,
          rationale: `${founderCount}位创始人，${hasExperience ? '具备' : '缺乏'}相关经验`,
        },
        {
          key: '市场因素',
          value: `${factors.market.score}%`,
          rationale: `TAM ${project.market.tam ? '$' + this.formatNumber(project.market.tam) : '未知'}`,
        },
        {
          key: '产品因素',
          value: `${factors.product.score}%`,
          rationale: `产品处于${project.product.stage}阶段`,
        },
        {
          key: '综合调整系数',
          value: adjustmentFactor.toFixed(2),
          rationale: '各因素加权平均',
        },
      ],
    };
  }

  /**
   * Berkus法
   * 适用于Pre-Revenue早期公司
   */
  private async berkusMethod(project: Project): Promise<ValuationResult> {
    // Berkus法：5个关键要素，每个最高500K
    const maxPerFactor = 500_000;
    let valuation = 0;

    const factors: Array<{ key: string; value: number; rationale: string }> = [];

    // 1. 好的创意/基本价值 (0-500K)
    const ideaValue = project.product.uniqueValueProposition.length > 50 ? maxPerFactor : maxPerFactor * 0.6;
    valuation += ideaValue;
    factors.push({
      key: '创意价值',
      value: ideaValue,
      rationale: '独特价值主张的清晰度和吸引力',
    });

    // 2. 原型/技术风险降低 (0-500K)
    const prototypeScores = {
      'idea': 0,
      'prototype': maxPerFactor * 0.4,
      'mvp': maxPerFactor * 0.7,
      'launched': maxPerFactor,
      'scaling': maxPerFactor,
    };
    const prototypeValue = prototypeScores[project.product.stage] || 0;
    valuation += prototypeValue;
    factors.push({
      key: '产品/技术',
      value: prototypeValue,
      rationale: `产品${project.product.stage}阶段的技术风险评估`,
    });

    // 3. 优质管理团队 (0-500K)
    const teamQuality = project.team.founders.length >= 2 ? maxPerFactor * 0.8 : maxPerFactor * 0.5;
    valuation += teamQuality;
    factors.push({
      key: '管理团队',
      value: teamQuality,
      rationale: `${project.team.founders.length}位创始人，团队${project.team.teamSize}人`,
    });

    // 4. 战略关系/市场风险降低 (0-500K)
    const hasPartnerships = project.traction?.partnerships && project.traction.partnerships.length > 0;
    const relationshipValue = hasPartnerships ? maxPerFactor * 0.7 : maxPerFactor * 0.3;
    valuation += relationshipValue;
    factors.push({
      key: '战略关系',
      value: relationshipValue,
      rationale: hasPartnerships ? `已建立${project.traction!.partnerships!.length}个战略合作` : '战略关系待建立',
    });

    // 5. 产品推出/销售风险降低 (0-500K)
    let salesValue = 0;
    if (project.traction?.customers && project.traction.customers >= 10) {
      salesValue = maxPerFactor;
    } else if (project.traction?.customers && project.traction.customers > 0) {
      salesValue = maxPerFactor * 0.6;
    } else if (project.product.stage === 'launched') {
      salesValue = maxPerFactor * 0.3;
    }
    valuation += salesValue;
    factors.push({
      key: '产品推出/销售',
      value: salesValue,
      rationale: project.traction?.customers
        ? `${project.traction.customers}个付费客户`
        : '销售尚未验证',
    });

    valuation = Math.round(valuation);

    return {
      method: 'berkus' as ValuationMethod,
      valuation,
      range: {
        low: Math.round(valuation * 0.8),
        mid: valuation,
        high: Math.round(valuation * 1.2),
      },
      assumptions: factors,
    };
  }

  /**
   * 风险因素总和法 (Risk Factor Summation Method)
   */
  private async riskFactorMethod(project: Project): Promise<ValuationResult> {
    // 基准估值
    const baseValuation = this.getBaselineValuation(project);

    // 12个风险因素，每个从-2到+2
    const risks = {
      management: 0, // 管理风险
      stage: 0, // 阶段风险
      legislation: 0, // 政策/法律风险
      manufacturing: 0, // 生产风险
      sales: 0, // 销售/市场风险
      funding: 0, // 资金风险
      competition: 0, // 竞争风险
      technology: 0, // 技术风险
      litigation: 0, // 诉讼风险
      international: 0, // 国际风险
      reputation: 0, // 声誉风险
      exit: 0, // 退出风险
    };

    // 评估各项风险
    // 管理风险
    if (project.team.founders.length >= 2 && project.team.founders.length <= 3) {
      risks.management = 1;
    } else if (project.team.founders.length === 1) {
      risks.management = -1;
    }

    // 阶段风险
    const stageRisks: Record<string, number> = {
      'idea': -2,
      'prototype': -1,
      'mvp': 0,
      'launched': 1,
      'scaling': 2,
    };
    risks.stage = stageRisks[project.product.stage] || 0;

    // 销售/市场风险
    if (project.traction?.customers && project.traction.customers >= 100) {
      risks.sales = 2;
    } else if (project.traction?.customers && project.traction.customers >= 10) {
      risks.sales = 1;
    } else if (!project.traction?.customers) {
      risks.sales = -2;
    }

    // 资金风险
    if (project.financials.expenses && project.financials.expenses.runway >= 12) {
      risks.funding = 1;
    } else if (project.financials.expenses && project.financials.expenses.runway < 6) {
      risks.funding = -2;
    }

    // 竞争风险
    if (project.market.competitors.length <= 3) {
      risks.competition = 1;
    } else if (project.market.competitors.length >= 10) {
      risks.competition = -1;
    }

    // 技术风险
    if (project.product.stage === 'launched' || project.product.stage === 'scaling') {
      risks.technology = 1;
    } else if (project.product.stage === 'idea') {
      risks.technology = -1;
    }

    // 计算总风险调整
    const totalRiskAdjustment = Object.values(risks).reduce((sum, r) => sum + r, 0);
    const adjustmentPerFactor = baseValuation * 0.025; // 每个风险因素±2.5%
    const valuation = Math.round(baseValuation + (totalRiskAdjustment * adjustmentPerFactor));

    return {
      method: 'risk-factor' as ValuationMethod,
      valuation,
      range: {
        low: Math.round(valuation * 0.75),
        mid: valuation,
        high: Math.round(valuation * 1.25),
      },
      assumptions: [
        {
          key: '基准估值',
          value: baseValuation,
          rationale: '行业和阶段基准',
        },
        {
          key: '风险调整总分',
          value: totalRiskAdjustment,
          rationale: '12个风险因素的综合评分（-24到+24）',
        },
        {
          key: '管理风险',
          value: risks.management,
          rationale: `${project.team.founders.length}位创始人`,
        },
        {
          key: '阶段风险',
          value: risks.stage,
          rationale: project.product.stage,
        },
        {
          key: '销售风险',
          value: risks.sales,
          rationale: project.traction?.customers ? `${project.traction.customers}个客户` : '无客户',
        },
        {
          key: '竞争风险',
          value: risks.competition,
          rationale: `${project.market.competitors.length}个竞争对手`,
        },
      ],
    };
  }

  /**
   * 可比公司法 (Comparable Company Method)
   * 适用于有收入的公司
   */
  private async comparableMethod(project: Project): Promise<ValuationResult> {
    if (!project.financials.revenue || project.financials.revenue.current === 0) {
      throw new Error('可比公司法需要有收入数据');
    }

    // 获取行业倍数（这里使用估算值，实际应该从数据库获取）
    const industryMultiples = this.getIndustryMultiples(project.industry, project.fundraising.currentStage);

    const revenue = project.financials.revenue.current;
    const arr = project.financials.metrics?.arr || revenue;

    // 使用收入倍数计算估值
    const valuation = Math.round(arr * industryMultiples.revenueMultiple);

    return {
      method: 'comparable' as ValuationMethod,
      valuation,
      range: {
        low: Math.round(arr * industryMultiples.revenueMultiple * 0.7),
        mid: valuation,
        high: Math.round(arr * industryMultiples.revenueMultiple * 1.3),
      },
      assumptions: [
        {
          key: 'ARR',
          value: arr,
          rationale: '年度经常性收入',
        },
        {
          key: '收入倍数',
          value: industryMultiples.revenueMultiple,
          rationale: `${project.industry}行业${project.fundraising.currentStage}阶段的中位数倍数`,
        },
      ],
      multiples: {
        revenueMultiple: industryMultiples.revenueMultiple,
        ebitdaMultiple: industryMultiples.ebitdaMultiple,
      },
    };
  }

  /**
   * 生成交易结构建议
   */
  generateDealStructure(
    project: Project,
    preMoney: number,
    investmentAmount?: number
  ): DealStructure {
    const investment = investmentAmount || project.fundraising.targetAmount;
    const postMoney = preMoney + investment;
    const newInvestorOwnership = investment / postMoney;

    // 计算股权稀释
    const existingOwnership = project.fundraising.previousRounds
      ? project.fundraising.previousRounds.reduce((sum, round) => {
          const roundPostMoney = (round.valuation || 0) + round.amount;
          return sum * (1 - round.amount / roundPostMoney);
        }, 1)
      : 1;

    const founderOwnership = existingOwnership * (1 - newInvestorOwnership) * 0.85; // 假设15%期权池
    const optionPool = 0.15 * (1 - newInvestorOwnership);
    const existingInvestorOwnership = 1 - newInvestorOwnership - founderOwnership - optionPool;

    return {
      investment: {
        amount: investment,
        currency: 'USD',
      },
      valuation: {
        preMoney,
        postMoney,
        method: 'Comprehensive valuation analysis',
      },
      equity: {
        newInvestorOwnership: Math.round(newInvestorOwnership * 10000) / 100,
        founderOwnership: Math.round(founderOwnership * 10000) / 100,
        existingInvestorOwnership: Math.round(existingInvestorOwnership * 10000) / 100,
        optionPool: Math.round(optionPool * 10000) / 100,
      },
      terms: {
        liquidationPreference: {
          multiple: 1,
          participating: false,
        },
        antiDilution: 'weighted-average',
        boardSeats: {
          founders: 2,
          investors: 1,
          independent: 1,
        },
        protectiveProvisions: [
          '增发新股',
          '出售公司',
          '修改公司章程',
          '分配股利',
          '增加债务超过一定金额',
        ],
        dragAlong: true,
        tagAlong: true,
        rightOfFirstRefusal: true,
      },
    };
  }

  // ===== 辅助方法 =====

  private getBaselineValuation(project: Project): number {
    // 根据地区、行业和阶段返回基准估值
    const stageBaselines: Record<string, number> = {
      'pre-seed': 2_000_000,
      'seed': 5_000_000,
      'series-a': 15_000_000,
      'series-b': 40_000_000,
      'series-c': 100_000_000,
      'series-d-plus': 250_000_000,
      'pre-ipo': 500_000_000,
    };

    let baseline = stageBaselines[project.fundraising.currentStage] || 5_000_000;

    // 根据行业调整（热门行业溢价）
    const hotIndustries = ['ai-ml', 'fintech', 'biotech'];
    if (hotIndustries.includes(project.industry)) {
      baseline *= 1.3;
    }

    return baseline;
  }

  private getIndustryMultiples(industry: string, stage: string): {
    revenueMultiple: number;
    ebitdaMultiple: number;
  } {
    // 简化版本，实际应该从数据库获取最新的行业数据
    const multiplesByIndustry: Record<string, { revenueMultiple: number; ebitdaMultiple: number }> = {
      'enterprise-software': { revenueMultiple: 10, ebitdaMultiple: 20 },
      'ai-ml': { revenueMultiple: 15, ebitdaMultiple: 25 },
      'fintech': { revenueMultiple: 8, ebitdaMultiple: 15 },
      'healthcare': { revenueMultiple: 7, ebitdaMultiple: 12 },
      'ecommerce': { revenueMultiple: 3, ebitdaMultiple: 8 },
      'b2b-saas': { revenueMultiple: 12, ebitdaMultiple: 22 },
    };

    return multiplesByIndustry[industry] || { revenueMultiple: 5, ebitdaMultiple: 10 };
  }

  private calculateWeightedValuation(
    results: ValuationResult[],
    project: Project
  ): { preMoney: number; postMoney: number; methodology: string } {
    // 根据项目阶段给不同方法分配权重
    let weights: Record<string, number> = {};

    if (!project.financials.revenue || project.financials.revenue.current === 0) {
      // Pre-revenue: 更依赖定性方法
      weights = {
        scorecard: 0.4,
        berkus: 0.35,
        'risk-factor': 0.25,
      };
    } else {
      // Has revenue: 可比公司法更重要
      weights = {
        scorecard: 0.25,
        berkus: 0.15,
        'risk-factor': 0.2,
        comparable: 0.4,
      };
    }

    let weightedSum = 0;
    let totalWeight = 0;

    for (const result of results) {
      const weight = weights[result.method] || 0;
      weightedSum += result.valuation * weight;
      totalWeight += weight;
    }

    const preMoney = Math.round(weightedSum / totalWeight);
    const postMoney = preMoney + project.fundraising.targetAmount;

    return {
      preMoney,
      postMoney,
      methodology: `加权平均法（${Object.entries(weights).map(([k, v]) => `${k}: ${v * 100}%`).join(', ')}）`,
    };
  }

  private getBenchmarkData(project: Project): ComprehensiveValuation['benchmarkData'] {
    // 这里应该从实际数据库获取，目前使用模拟数据
    const stageMedians: Record<string, number> = {
      'pre-seed': 3_000_000,
      'seed': 8_000_000,
      'series-a': 20_000_000,
      'series-b': 50_000_000,
      'series-c': 120_000_000,
    };

    return {
      industryMedian: stageMedians[project.fundraising.currentStage] || 10_000_000,
      stageMedian: stageMedians[project.fundraising.currentStage] || 10_000_000,
      recentComparables: [
        // 示例数据
      ],
    };
  }

  private suggestDealTerms(
    project: Project,
    preMoney: number
  ): ComprehensiveValuation['dealTerms'] {
    const investment = project.fundraising.targetAmount;
    const postMoney = preMoney + investment;
    const equity = (investment / postMoney) * 100;

    return {
      suggestedInvestment: investment,
      suggestedEquity: Math.round(equity * 100) / 100,
      suggestedValuation: preMoney,
      liquidationPreference: '1x非参与优先清算权',
      antiDilution: '加权平均反稀释条款',
    };
  }

  private generateAnalysis(
    project: Project,
    recommendedValuation: { preMoney: number; postMoney: number },
    methods: ValuationResult[]
  ): string {
    const parts: string[] = [];

    parts.push(`基于对${project.name}的综合分析，我们采用了多种估值方法进行评估。`);

    parts.push(
      `\n推荐的Pre-money估值为$${this.formatNumber(recommendedValuation.preMoney)}，` +
      `投后估值为$${this.formatNumber(recommendedValuation.postMoney)}。`
    );

    // 分析各方法的结果
    const valuations = methods.map(m => m.valuation);
    const min = Math.min(...valuations);
    const max = Math.max(...valuations);
    const range = ((max - min) / min * 100).toFixed(0);

    parts.push(
      `\n各估值方法的结果范围为$${this.formatNumber(min)}至$${this.formatNumber(max)}，` +
      `波动范围${range}%，显示出${range < '30' ? '较高的一致性' : '一定的不确定性'}。`
    );

    // 关键因素分析
    parts.push('\n关键估值驱动因素：');
    if (project.market.tam && project.market.tam >= 10_000_000_000) {
      parts.push(`- 巨大的市场机会（TAM $${this.formatNumber(project.market.tam)}）支撑较高估值`);
    }
    if (project.traction?.customers && project.traction.customers >= 50) {
      parts.push(`- 已验证的市场牵引力（${project.traction.customers}+客户）`);
    }
    if (project.product.stage === 'scaling') {
      parts.push('- 产品已进入规模化阶段，执行风险降低');
    }

    return parts.join('\n');
  }

  private identifyValuationRisks(project: Project, methods: ValuationResult[]): string[] {
    const risks: string[] = [];

    // 估值方法差异过大
    const valuations = methods.map(m => m.valuation);
    const avg = valuations.reduce((a, b) => a + b, 0) / valuations.length;
    const maxDeviation = Math.max(...valuations.map(v => Math.abs(v - avg) / avg));

    if (maxDeviation > 0.4) {
      risks.push('不同估值方法结果差异较大（>40%），估值存在较高不确定性');
    }

    // 缺乏收入数据
    if (!project.financials.revenue || project.financials.revenue.current === 0) {
      risks.push('尚无收入，估值主要基于定性分析，实际价值需市场验证');
    }

    // 产品早期
    if (project.product.stage === 'idea' || project.product.stage === 'prototype') {
      risks.push('产品处于早期阶段，技术和市场风险较高');
    }

    // 竞争激烈
    if (project.market.competitors.length > 10) {
      risks.push('市场竞争激烈，可能影响未来增长和估值');
    }

    return risks;
  }

  private formatNumber(num: number): string {
    if (num >= 1_000_000_000) {
      return `${(num / 1_000_000_000).toFixed(1)}B`;
    } else if (num >= 1_000_000) {
      return `${(num / 1_000_000).toFixed(1)}M`;
    } else if (num >= 1_000) {
      return `${(num / 1_000).toFixed(1)}K`;
    }
    return num.toFixed(0);
  }
}

